<script setup lang="ts">
import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import type { MenuItem } from '../lib/context-menu'
import { t } from '../lib/i18n'
const props=defineProps<{items:MenuItem[];x:number;y:number}>(),emit=defineEmits<{close:[]}>()
const panels=ref<{items:MenuItem[];x:number;y:number;active:number}[]>([{items:props.items,x:props.x,y:props.y,active:-1}])
const originalFocus=document.activeElement as HTMLElement|null
async function fit(){await nextTick();for(const [index,panel]of panels.value.entries()){const element=document.querySelector<HTMLElement>(`.designer-context-menu[data-level="${index}"]`);if(element){panel.x=Math.max(6,Math.min(panel.x,window.innerWidth-element.offsetWidth-6));panel.y=Math.max(6,Math.min(panel.y,window.innerHeight-element.offsetHeight-6))}}}
function close(){emit('close');originalFocus?.focus?.({preventScroll:true})}
function choose(item:MenuItem,level:number,event?:MouseEvent){if(item.disabled||item.separator)return;if(item.items){const target=event?.currentTarget as HTMLElement|undefined,rect=target?.getBoundingClientRect();panels.value.splice(level+1);panels.value.push({items:item.items,x:rect?.right??panels.value[level]!.x+210,y:rect?.top??panels.value[level]!.y,active:-1});void fit()}else{close();item.action?.()}}
function hover(index:number,level:number,event:MouseEvent){const panel=panels.value[level]!;panel.active=index;const item=panel.items[index]!;if(item.items&&!item.disabled)choose(item,level,event);else panels.value.splice(level+1)}
function outside(event:Event){if(!(event.target as HTMLElement)?.closest('.designer-context-menu'))close()}
function keydown(event:KeyboardEvent){const level=panels.value.length-1,panel=panels.value[level]!;if(event.key==='Escape'){event.preventDefault();close();return}if(event.key==='ArrowLeft'&&level){event.preventDefault();panels.value.pop();return}if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const direction=event.key==='ArrowDown'?1:-1;for(let attempt=0;attempt<panel.items.length;attempt++){panel.active=(panel.active+direction+panel.items.length)%panel.items.length;if(!panel.items[panel.active]?.disabled&&!panel.items[panel.active]?.separator)break}void nextTick(()=>document.querySelector<HTMLElement>(`.designer-context-menu[data-level="${level}"] [data-index="${panel.active}"]`)?.focus())}if(event.key==='Enter'||event.key==='ArrowRight'){event.preventDefault();const item=panel.items[panel.active];if(item)choose(item,level)}}
onMounted(()=>{document.addEventListener('pointerdown',outside,true);document.addEventListener('keydown',keydown,true);window.addEventListener('blur',close);window.addEventListener('resize',close);void fit()})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside,true);document.removeEventListener('keydown',keydown,true);window.removeEventListener('blur',close);window.removeEventListener('resize',close)})
</script>
<template><Teleport to="body"><div v-for="(panel,level) in panels" :key="level" role="menu" class="designer-context-menu" :data-level="level" :style="{left:`${panel.x}px`,top:`${panel.y}px`}" @contextmenu.prevent><template v-for="(item,index) in panel.items" :key="index"><hr v-if="item.separator" role="separator"/><button v-else role="menuitem" :aria-label="t(item.label)" :data-index="index" :disabled="item.disabled" :aria-haspopup="item.items?'menu':undefined" :class="{active:panel.active===index}" @mouseenter="hover(index,level,$event)" @click="choose(item,level,$event)"><span class="menu-check">{{ item.checked?'✓':'' }}</span><span>{{ t(item.label) }}</span><kbd v-if="item.shortcut">{{ item.shortcut }}</kbd><span v-if="item.items" class="menu-arrow">›</span></button></template></div></Teleport></template>
<style scoped>
.designer-context-menu{position:fixed;z-index:10000;min-width:220px;max-width:min(340px,calc(100vw - 12px));max-height:calc(100dvh - 12px);overflow:auto;background:var(--surface,#fff);color:var(--text,#242424);border:1px solid #d4dbe4;border-radius:7px;padding:5px;box-shadow:0 8px 30px #1020302b;font-size:12px}.designer-context-menu button{display:flex;align-items:center;text-align:left;width:100%;gap:7px;padding:8px 6px;border-radius:4px;min-height:31px;white-space:nowrap}.designer-context-menu button:hover,.designer-context-menu button.active{background:#edf4fb}.designer-context-menu button:disabled{opacity:.45}.designer-context-menu kbd{margin-left:auto;padding-left:16px}.menu-check{width:13px;flex-shrink:0}.menu-arrow{margin-left:auto}.designer-context-menu hr{border:0;border-top:1px solid #e5e9ed;margin:4px}
</style>
